import{GENRES,TRACKS,defaults,generate,midiBytes,isAudible,stepsFor,trackFor,swingRatio,effectiveDensity}from'./engine.js';
import{Player,renderWav}from'./audio.js';
import{REFERENCES,COMMON_LINKS}from'./references.js';
import{FOUNDATIONS}from'./genre-foundations.js';
import{LENSES,lensFor}from'./livepilot-lenses.js';
const $=id=>document.getElementById(id),STORE='pocket-lab-v1',LIBRARY='pocket-lab-patterns-v1';
let state=defaults(),bar=0,selectedTrack=3,lastStep=-1,library=[],toastTimer,tapTimes=[];
function valid(s){return s&&GENRES[s.genre]&&(s.lens===undefined||Object.hasOwn(LENSES,s.lens))&&(s.swingBase===undefined||[8,16].includes(s.swingBase))&&[1,2,4,8].includes(s.bars)&&Number.isFinite(s.bpm)&&s.bpm>=40&&s.bpm<=220&&['909','808','room'].includes(s.kit)&&['intro','groove','build','fill'].includes(s.section)&&['density','swing','humanize','volume'].every(k=>Number.isFinite(s[k])&&s[k]>=0&&s[k]<=(k==='swing'?60:100))&&Number.isInteger(s.variant)&&s.variant>=0&&['muted','solo','locked'].every(k=>Array.isArray(s[k])&&s[k].length===6&&s[k].every(v=>typeof v==='boolean'))&&Array.isArray(s.pattern)&&s.pattern.length===s.bars&&s.pattern.every(b=>Array.isArray(b)&&b.length===6&&b.every(r=>Array.isArray(r)&&r.length===stepsFor(s)&&r.every(v=>Number.isInteger(v)&&v>=0&&v<=127)));}
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3200);}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Browser storage is unavailable. You can still export your pattern.');}}
try{const s=JSON.parse(localStorage.getItem(STORE));if(valid(s))state=s;const a=JSON.parse(localStorage.getItem(LIBRARY));if(Array.isArray(a))library=a.filter(x=>x&&typeof x.id==='string'&&valid(x.state));}catch{}
if(!state.pattern.length)state.pattern=generate(state);
const player=new Player(()=>state,position=>{lastStep=position;const next=Math.floor(position/stepsFor(state));if(position>=0&&$('follow').checked&&next!==bar){bar=next;renderGrid();renderTabs();}document.querySelectorAll('.step.current').forEach(el=>el.classList.remove('current'));if(position>=0&&next===bar)document.querySelectorAll(`.step[data-step="${position%stepsFor(state)}"]`).forEach(el=>el.classList.add('current'));document.querySelectorAll('.bar-tab').forEach((el,i)=>el.classList.toggle('live',position>=0&&i===next));updatePlay();},message=>toast(message));
function updatePlay(){$('playIcon').textContent=player.playing?'Ⅱ':'▶';$('play').classList.toggle('playing',player.playing);$('play').setAttribute('aria-label',player.playing?'Stop playback':'Play pattern');}
function renderGenres(){
 const savedScroll=$('genres').scrollTop;$('genres').replaceChildren();const query=$('genreSearch').value.trim().toLowerCase(),family=$('genreFamily').value;
 const entries=Object.entries(GENRES).filter(([key,g])=>(family==='all'||g.family===family)&&(!query||[g.name,g.tag,g.family,key].join(' ').toLowerCase().includes(query)));
 $('genreCount').textContent=entries.length+' / '+Object.keys(GENRES).length+' STYLES';
 entries.forEach(([key,g])=>{const b=document.createElement('button');b.className='genre-button'+(state.genre===key?' active':'');b.setAttribute('aria-pressed',String(state.genre===key));b.title='Suggested study range: '+g.range;b.innerHTML=`<span class="genre-icon" aria-hidden="true">${g.icon}</span><span><b>${g.name}</b><small>${g.tag}</small></span>`;b.onclick=()=>{if(key===state.genre)return;player.stop();state.genre=key;state.bpm=g.tempo;state.swing=g.swing;state.swingBase=g.swingBase??16;state.humanize=g.humanize??20;state.density=50;state.kit=g.kit;state.variant=0;state.locked.fill(false);state.pattern=generate(state);bar=0;render();persist();toast(`${g.name} foundation loaded · ${g.tempo} BPM`);};$('genres').append(b);});
 $('genres').scrollTop=savedScroll;
 if(!entries.length){const p=document.createElement('p');p.className='no-genres';p.textContent='No matching styles. Try another search or family.';$('genres').append(p);}
}
function renderTabs(){$('barTabs').replaceChildren();for(let i=0;i<state.bars;i++){const b=document.createElement('button');b.className='bar-tab'+(i===bar?' selected':'')+(lastStep>=0&&Math.floor(lastStep/stepsFor(state))===i?' live':'');b.textContent=`BAR ${i+1}`;b.setAttribute('aria-pressed',String(i===bar));b.onclick=()=>{bar=i;renderTabs();renderGrid();};$('barTabs').append(b);}}
function renderGrid(){
 const g=GENRES[state.genre];document.querySelector('.sequence-inner').style.setProperty('--step-count',g.steps);document.querySelector('.sequence-inner').style.minWidth=Math.max(570,g.steps*25+150)+'px';$('lanes').replaceChildren();
 TRACKS.forEach((_,r)=>{const track=trackFor(state,r);const row=document.createElement('div');row.className='lane'+(!isAudible(state,r)?' muted':'');row.style.setProperty('--track',track.color);const info=document.createElement('div');info.className='lane-info';const dot=document.createElement('span');dot.className='track-dot';info.append(dot);const name=document.createElement('button');name.className='lane-name'+(selectedTrack===r?' selected':'');name.textContent=track.name;name.title='Show '+track.name+' velocities';name.onclick=()=>{selectedTrack=r;renderGrid();};info.append(name);const tools=document.createElement('div');tools.className='lane-tools';[['muted','M','Mute'],['solo','S','Solo'],['locked','⌑','Lock lane during generation']].forEach(([key,letter,label])=>{const btn=document.createElement('button');btn.className=(key==='locked'?'lock ':'')+(state[key][r]?'on':'');btn.textContent=letter;btn.title=`${label}: ${track.name}`;btn.setAttribute('aria-label',`${label}: ${track.name}`);btn.setAttribute('aria-pressed',String(state[key][r]));btn.onclick=()=>{state[key][r]=!state[key][r];renderGrid();persist();};tools.append(btn);});info.append(tools);row.append(info);const steps=document.createElement('div');steps.className='steps';for(let s=0;s<g.steps;s++){const v=state.pattern[bar][r][s],anchor=g.anchors[r].includes(s),btn=document.createElement('button');btn.className='step'+(Math.floor(s/(g.steps/4))%2?' group-alt':'')+(v?' active':'')+(v&&v<55?' ghost':'')+(v&&anchor?' anchor':'')+(lastStep>=0&&Math.floor(lastStep/stepsFor(state))===bar&&lastStep%stepsFor(state)===s?' current':'');btn.dataset.step=s;btn.title=`${track.name} · bar ${bar+1} · step ${s+1} · ${v?'velocity '+v:'off'}${anchor?' · study anchor':''}`;btn.setAttribute('aria-label',btn.title);btn.setAttribute('aria-pressed',String(!!v));btn.onclick=e=>{selectedTrack=r;state.pattern[bar][r][s]=e.shiftKey?(v<1?36:v<55?76:v<100?114:36):(v?0:r<3?108:78);renderGrid();persist();};steps.append(btn);}row.append(steps);$('lanes').append(row);});
 $('velocityLabel').textContent=trackFor(state,selectedTrack).name.toUpperCase();$('velocities').replaceChildren();state.pattern[bar][selectedTrack].forEach((v,s)=>{const b=document.createElement('button');b.className='velocity';b.style.height=(v?Math.max(3,v/127*24):2)+'px';b.style.opacity=v?'.75':'.13';b.title=`Step ${s+1}: velocity ${v}. Click to cycle.`;b.setAttribute('aria-label',b.title);b.onclick=()=>{if(!v){toast('Add a hit in the grid first.');return;}state.pattern[bar][selectedTrack][s]=v<55?76:v<100?114:36;persist();renderGrid();};$('velocities').append(b);});
}
function render(){
 const g=GENRES[state.genre],f=FOUNDATIONS[state.genre],lens=lensFor(state);
 renderGenres();renderBeatNumbers();renderTabs();renderGrid();
 $('patternName').textContent=g.names[state.variant%g.names.length];$('genreMeta').textContent=g.name.toUpperCase();$('lengthMeta').textContent=`${state.bars} ${state.bars===1?'BAR':'BARS'}`;$('variantMeta').textContent=`VARIATION ${String(state.variant+1).padStart(2,'0')}`;
 $('lensMeta').hidden=!state.lens||state.lens==='none';$('lensMeta').textContent='LP · '+lens.short.toUpperCase();
 for(const k of['bpm','kit','bars','density','swing','swingBase','humanize','volume','section'])$(k).value=state[k]??16;
 renderControls();renderLens();$('grammarTitle').textContent=g.name;$('grammarIntro').textContent=f.summary;$('genreSource').href=REFERENCES[state.genre].links[0][1];$('genreSource').textContent='Genre reference ↗';
 const cards=[...f.conventions,['This app’s drum study',`${g.steps} steps per bar, 4/4, four authored motif families. The marked anchors and exact placements are Pocket Lab’s choices.`]];
 $('grammarCards').replaceChildren();cards.forEach(([title,body],i)=>{const c=document.createElement('div');c.className='grammar-card';const n=document.createElement('span'),b=document.createElement('b'),p=document.createElement('p');n.textContent='0'+(i+1);b.textContent=title;p.textContent=body;c.append(n,b,p);$('grammarCards').append(c);});
 $('phraseHint').textContent=phraseHints[state.section]+(state.lens&&state.lens!=='none'?' Active production lens: '+lens.short+'.':' No Livepilot production lens applied.');
 $('savedCount').textContent=library.length;updatePlay();
}
function renderLens(){
 const l=lensFor(state),active=!!l.packet;$('productionLens').value=state.lens??'none';$('lensSummary').textContent=l.description;$('lensIntent').textContent=l.upstream??'The foundation is an authored drum study informed by independent genre references. It is not a universal definition of the genre.';$('lensSource').hidden=!active;$('lensSource').href=l.sourceURL??'';$('lensSource').textContent='Livepilot concept packet ↗';$('lensState').textContent=active?'OPTIONAL LENS ON':'OFF BY DEFAULT';document.querySelector('.production-lens').classList.toggle('is-active',active);
}
function renderControls(){
 const cap=lensFor(state).rules.maxDensity??100,effective=effectiveDensity(state);$('density').max=100;$('density').value=state.density;$('density').title=cap<100?'Requested density '+state.density+'; active Livepilot lens caps generated detail at '+cap+'.':'Density of the authored genre study; no Livepilot cap.';
 $('densityOut').textContent=effective<state.density?effective+' (lens cap)':effective<25?'Sparse':effective<65?'Balanced':effective<80?'Detailed':'Busy';
 const tuplets=GENRES[state.genre].steps!==16;$('swingOut').textContent=tuplets?'Tuplets':swingRatio(state)+'%';$('swing').disabled=tuplets;$('swingBase').disabled=tuplets;$('swingHint').textContent=tuplets?'Authored tuplets; swing is bypassed.':'50% = straight · delays alternate '+(state.swingBase===8?'eighths.':'sixteenths.');$('humanizeOut').textContent=state.humanize+'%';
 for(const k of['density','swing','humanize','volume'])$(k).style.setProperty('--progress',(state[k]/Number($(k).max)*100)+'%');
}
$('swingBase').onchange=()=>{state.swingBase=Number($('swingBase').value);renderControls();persist();};
function renderBeatNumbers(){const g=GENRES[state.genre],perBeat=g.steps/4;$('beatNumbers').replaceChildren();for(let i=0;i<g.steps;i++){const el=document.createElement('span');el.className='beat-number'+(i%perBeat===0?' strong':'');el.textContent=i%perBeat===0?i/perBeat+1:g.steps===16?['','e','&','a'][i%4]:'·';$('beatNumbers').append(el);}document.querySelector('.grid-label').textContent=g.grid??'1/16 GRID';}
$('genreSearch').oninput=renderGenres;$('genreFamily').onchange=renderGenres;
$('play').onclick=async()=>{if(player.playing)player.stop();else await player.start();updatePlay();};$('stop').onclick=()=>{player.stop();bar=0;renderTabs();renderGrid();};
$('bpm').onchange=()=>{const value=Number($('bpm').value);state.bpm=Number.isFinite(value)?Math.min(220,Math.max(40,Math.round(value))):GENRES[state.genre].tempo;$('bpm').value=state.bpm;player.restart();persist();};
$('tap').onclick=()=>{const now=performance.now();if(tapTimes.length&&now-tapTimes.at(-1)>2000)tapTimes=[];tapTimes.push(now);tapTimes=tapTimes.slice(-5);if(tapTimes.length>1){state.bpm=Math.min(220,Math.max(40,Math.round(60000/((now-tapTimes[0])/(tapTimes.length-1)))));$('bpm').value=state.bpm;player.restart();persist();}};
for(const key of['swing','humanize','volume'])$(key).oninput=()=>{state[key]=Number($(key).value);renderControls();persist();};
$('density').oninput=()=>{state.density=Number($('density').value);state.pattern=generate(state,state.pattern);renderControls();renderGrid();persist();};
$('kit').onchange=()=>{state.kit=$('kit').value;persist();};
$('bars').onchange=()=>{state.bars=Number($('bars').value);state.pattern=generate(state,state.pattern);bar=Math.min(bar,state.bars-1);player.restart();render();persist();};
$('section').onchange=()=>{state.section=$('section').value;state.pattern=generate(state,state.pattern);renderGrid();persist();toast($('section').selectedOptions[0].textContent+' applied.');};
$('generate').onclick=()=>{state.variant++;state.pattern=generate(state,state.pattern);render();persist();toast(state.locked.every(Boolean)?'All lanes are locked. Unlock a lane to vary it.':'Motif '+(state.variant%4+1)+'/4 · study anchors kept, unlocked lanes varied.');};
function open(id){$(id).showModal();}
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}));
$('workspaceNav').onclick=()=>document.querySelector('.workspace').scrollIntoView({behavior:'smooth',block:'start'});$('aboutNav').onclick=()=>open('aboutDialog');
$('genreRefs').onclick=()=>{
 const ref=REFERENCES[state.genre],l=lensFor(state);$('referencesTitle').textContent=GENRES[state.genre].name;$('referenceFoundation').textContent=FOUNDATIONS[state.genre].summary;$('referenceCaveat').textContent=ref.caveat;
 const appendLinks=(id,items)=>{$(id).replaceChildren();for(const[title,url]of items){const li=document.createElement('li'),a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.textContent=title+' ↗';li.append(a);$(id).append(li);}};
 appendLinks('referenceList',ref.links);appendLinks('technicalReferenceList',COMMON_LINKS);$('referenceLensSummary').textContent=l.packet?l.description+' '+l.upstream:'Livepilot production lens is off. Its optional density caps and development rules are not applied to new generation.';$('referenceLensSource').hidden=!l.packet;$('referenceLensSource').href=l.sourceURL??'';open('referencesDialog');
};
for(const[id,l]of Object.entries(LENSES)){const option=document.createElement('option');option.value=id;option.textContent=l.name;$('productionLens').append(option);}
$('productionLens').onchange=()=>{state.lens=$('productionLens').value;state.pattern=generate(state,state.pattern);render();persist();toast((state.lens==='none'?'Livepilot lens off':'Livepilot lens: '+lensFor(state).short)+' · locked steps preserved.');};

function saveLibrary(){try{localStorage.setItem(LIBRARY,JSON.stringify(library));$('savedCount').textContent=library.length;return true;}catch{toast('Could not save in this browser. Export MIDI or WAV instead.');return false;}}
$('save').onclick=()=>{const previous=library.slice();library.unshift({id:crypto.randomUUID(),name:$('patternName').textContent,created:Date.now(),state:structuredClone(state)});if(saveLibrary())toast('Pattern saved to My patterns.');else library=previous;};
function renderLibrary(){$('libraryList').replaceChildren();if(!library.length){const empty=document.createElement('p');empty.className='empty-library';empty.textContent='Your collection starts here. Save a pattern you like and it will be waiting in this browser.';$('libraryList').append(empty);return;}library.forEach(item=>{const row=document.createElement('div');row.className='library-item';const text=document.createElement('div'),b=document.createElement('b'),small=document.createElement('small');b.textContent=item.name;small.textContent=`${GENRES[item.state.genre].name} · ${item.state.bpm} BPM · ${item.state.bars} bars${item.state.lens&&item.state.lens!=='none'?' · '+lensFor(item.state).short:''}`;text.append(b,small);const load=document.createElement('button');load.className='button light';load.textContent='Load ↗';load.onclick=()=>{player.stop();state={...structuredClone(item.state),swingBase:item.state.swingBase??16,lens:item.state.lens??'none'};bar=0;render();persist();$('libraryDialog').close();toast('Saved pattern loaded.');};const del=document.createElement('button');del.className='delete';del.textContent='×';del.title='Delete '+item.name;del.setAttribute('aria-label',del.title);del.onclick=()=>{const prev=library;library=library.filter(x=>x.id!==item.id);if(saveLibrary())renderLibrary();else library=prev;};row.append(text,load,del);$('libraryList').append(row);});}
$('libraryNav').onclick=()=>{renderLibrary();open('libraryDialog');};
$('export').onclick=()=>{$('exportDescription').textContent=`${GENRES[state.genre].name} · ${state.bpm} BPM · ${state.bars}-bar ${state.section}${state.lens&&state.lens!=='none'?' · LP: '+lensFor(state).short:''} · ${$('kit').selectedOptions[0].textContent}`;open('exportDialog');};
function download(data,mime,ext){const url=URL.createObjectURL(new Blob([data],{type:mime})),a=document.createElement('a');a.href=url;a.download=`pocket-lab-${state.genre}-${state.bpm}bpm-${state.bars}bars${state.lens&&state.lens!=='none'?'-lp-'+state.lens:''}.${ext}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('exportMidi').onclick=()=>{download(midiBytes(state),'audio/midi','mid');toast('MIDI exported · full phrase with groove timing.');};
$('exportWav').onclick=async()=>{const btn=$('exportWav');btn.disabled=true;try{toast('Rendering your audio loop…');const snapshot=structuredClone(state),data=await renderWav(snapshot);download(data,'audio/wav','wav');toast('WAV exported · ready for your session.');}catch(e){toast('Audio export failed: '+e.message);}finally{btn.disabled=false;}};
$('reset').onclick=()=>{player.stop();state=defaults();state.pattern=generate(state);bar=0;render();persist();toast('Workspace reset. Saved patterns are still in your collection.');};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement?.tagName)||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();$('play').click();}if(e.code==='KeyG'&&!e.repeat)$('generate').click();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&player.playing){player.stop();toast('Playback stopped while the tab was hidden.');}});
state.swingBase??=16;
state.lens??='none';
const phraseHints={groove:'Main groove: repeat the authored motif with a related phrase response.',intro:'Intro: preserve study anchors while reducing supporting detail.',build:'Build: develop upper detail across the phrase; a selected production lens can change how that development works.',fill:'Fill: add an authored response in the final bar. The genre study’s anchors remain.'};
render();
